export function turnGuideHTML(id='london',turn=1,state=null){
 const p=TURN_PHASES.find(p=>p.id===id)||TURN_PHASES[0],index=TURN_PHASES.indexOf(p);
 const scenarioNotes=state?`<details class="paper-card"><summary>${scenarioFor(state).label} · starting setup reminders</summary><ol>${setupInstructions(state.scenario).map(t=>`<li>${t}</li>`).join('')}</ol></details>${p.id==='london'&&scenarioFor(state).deregulationVote&&!state.laws.deregulation?'<div class="notice">Before London Season, check whether Standing or Debt permits or requires a special Deregulation vote. Record the table’s vote in Game actions → Special session · Deregulation.</div>':''}${state.laws.deregulation&&['family','hiring','operations','london'].includes(p.id)?'<div class="notice"><b>Deregulation is active.</b> After Family and before Hiring, resolve the Firms phase: firm investments, then secret firm strategies. When flipping a family board to form a firm, keep its opportunity marker on the same family action. At the start of each Presidency’s operations, firms reveal matching strategies and check for trade; resolve trade initiative and orders under the Deregulation rules. Firms and the Company may each fill previously filled orders for half their listed value, rounded down. Resolve firm retirements, dividends, expenses and scoring on the table (rulebook pp. 37–41).</div>':''}`:'';
 return `${scenarioNotes}<div class="guide-intro"><p>A quick reference for ${state?scenarioFor(state).label:'1710'}. Follow passed laws and card-specific exceptions. Reading this guide does not change your campaign.</p></div><div class="guide-phase-tabs" role="group" aria-label="Turn phases">${TURN_PHASES.map(x=>`<button data-guide-phase="${x.id}" aria-pressed="${x.id===p.id}">${x.roman} · ${x.short}</button>`).join('')}</div><article class="paper-card guide-card"><p class="eyebrow">PHASE ${p.roman} · RULEBOOK ${p.pages.includes('–')?'PP.':'P.'} ${p.pages}</p><h3>${p.name}</h3><p class="guide-summary">${p.summary}</p>${p.id==='london'&&turn===1?'<div class="notice">Your campaign is on turn 1: skip the London Season.</div>':''}<ol class="guide-steps">${p.steps.map(step=>`<li>${step}</li>`).join('')}</ol>${p.extra||''}<div class="guide-app"><h4>Using the companion</h4><p>${p.app}</p></div><div class="guide-navigation">${index?`<button data-guide-phase="${TURN_PHASES[index-1].id}">← ${TURN_PHASES[index-1].short}</button>`:''}${index<8?`<button data-guide-phase="${TURN_PHASES[index+1].id}">${TURN_PHASES[index+1].short} →</button>`:''}</div></article>`;
}
